import * as Phaser from 'phaser';
import { ACCENT, VILLAIN } from './palette';
import { bandRect, bolt, forge, outline, path, poly, rand, seeded } from './draw';
import { buildAllRealms } from './realm';

/**
 * Arena texture entry point.
 *
 * Per-realm sky, parallax silhouettes and platform material are generated by
 * the shared config-driven renderer in `realm.ts` — one implementation for all
 * six realms, each contributing only a `RealmEnvironment`. What remains here
 * are the realm-agnostic props shared across scenes.
 */
export function buildArena(scene: Phaser.Scene) {
  buildAllRealms(scene);

  // Soft cloud band used in the intro cinematic and the sky realms.
  forge(scene, 'cloud_band', 1024, 260, (g) => {
    const r = seeded(211);
    for (let i = 0; i < 40; i++) {
      const x = r() * 1024;
      const y = 40 + r() * 180;
      const w = 160 + r() * 340;
      const h = 30 + r() * 70;
      g.fillStyle(0x1b2236, 0.08 + r() * 0.1);
      g.fillEllipse(x, y, w, h);
    }
  });

  // Reusable lightning streak for storm flashes.
  forge(scene, 'lightning_streak', 180, 420, (g) => {
    const r = seeded(307);
    bolt(g, { x: 90, y: 0 }, { x: 90 + rand(r, -40, 40), y: 420 }, VILLAIN.energy, 4, 34, 12, r, 0.9);
    bolt(g, { x: 90, y: 60 }, { x: 150, y: 260 }, VILLAIN.energy, 2.4, 20, 7, r, 0.6);
  });

  /* ---- Static hazard props -------------------------------------------
     Shapes are deliberately distinct from platform silhouettes: spikes are
     upward triangles, emitters are hexagonal housings, corruption is a
     ragged organic blob. Colour alone never signals danger. */

  // Spike bed — tiles horizontally along a ground run.
  forge(scene, 'hazard_spikes', 64, 48, (g) => {
    for (let i = 0; i < 4; i++) {
      const x = i * 16;
      poly(g, [{ x, y: 48 }, { x: x + 8, y: 4 }, { x: x + 16, y: 48 }], 0x2b3a4d, 1);
      poly(g, [{ x: x + 5, y: 48 }, { x: x + 8, y: 8 }, { x: x + 11, y: 48 }], 0xd9e8f2, 0.9);
    }
    g.fillStyle(0x111820, 1);
    g.fillRect(0, 44, 64, 4);
  });

  // Laser emitter housing — top and bottom of a gate.
  forge(scene, 'hazard_emitter', 36, 28, (g) => {
    poly(
      g,
      [{ x: 4, y: 0 }, { x: 32, y: 0 }, { x: 36, y: 14 }, { x: 32, y: 28 }, { x: 4, y: 28 }, { x: 0, y: 14 }],
      0x1d2430,
      1
    );
    g.lineStyle(1.5, 0x8395a5, 0.9);
    g.strokeRect(5, 5, 26, 18);
    g.fillStyle(0xff243d, 1);
    g.fillCircle(18, 14, 4);
  });

  // Corruption patch — organic, clearly not a surface you can stand on.
  forge(scene, 'hazard_corruption', 128, 40, (g) => {
    const r = seeded(733);
    g.fillStyle(0x18070c, 0.95);
    g.fillEllipse(64, 28, 126, 28);
    for (let i = 0; i < 18; i++) {
      g.fillStyle(r() > 0.5 ? 0xff243d : 0xc9102b, 0.25 + r() * 0.5);
      g.fillEllipse(r() * 128, 18 + r() * 20, 10 + r() * 30, 6 + r() * 14);
    }
    for (let i = 0; i < 7; i++) {
      const x = r() * 128;
      path(g, [{ x, y: 34 }, { x: x + rand(r, -6, 6), y: 6 + r() * 12 }], 0xff6678, 0.5, 1.4);
    }
  });

  // Security door panel — slides down from a fixed housing. Warning
  // chevrons read as "industrial machinery," distinct from every other
  // hazard's organic/energy language.
  forge(scene, 'hazard_door_panel', 48, 220, (g) => {
    bandRect(g, 0, 0, 48, 220, 0x2b3a4d, 0x111820, 20);
    for (let y = 10; y < 220; y += 26) {
      poly(
        g,
        [{ x: 6, y }, { x: 24, y: y + 10 }, { x: 42, y }, { x: 42, y: y + 4 }, { x: 24, y: y + 14 }, { x: 6, y: y + 4 }],
        0xff243d,
        0.55
      );
    }
    g.lineStyle(2, 0x8395a5, 0.8);
    g.strokeRect(2, 2, 44, 216);
  });

  // Door housing — the fixed frame the panel slides within.
  forge(scene, 'hazard_door_housing', 56, 24, (g) => {
    g.fillStyle(0x111820, 1);
    g.fillRect(0, 0, 56, 24);
    g.lineStyle(2, 0x8395a5, 0.9);
    g.strokeRect(1, 1, 54, 22);
    g.fillStyle(0xff243d, 1);
    g.fillCircle(10, 12, 3);
    g.fillCircle(46, 12, 3);
  });

  // Animated molten surface drawn under the ground lip in the fire realms.
  forge(scene, 'lava_surface', 512, 64, (g) => {
    const r = seeded(419);
    g.fillStyle(ACCENT.magma, 1);
    g.fillRect(0, 0, 512, 64);
    for (let i = 0; i < 40; i++) {
      g.fillStyle(r() > 0.5 ? ACCENT.emberHot : ACCENT.ember, 0.2 + r() * 0.5);
      g.fillEllipse(r() * 512, r() * 64, 20 + r() * 90, 6 + r() * 16);
    }
    g.fillStyle(ACCENT.emberHot, 0.5);
    g.fillRect(0, 0, 512, 4);
  });

  // Interactive Power Relay & Data Terminal (used in Stage 1 & Stage 5)
  forge(scene, 'interactive_terminal', 48, 64, (g) => {
    // Pedestal base
    g.fillStyle(0x1a2332, 1);
    g.fillRect(4, 32, 40, 32);
    g.lineStyle(2, 0x4a6d87, 0.9);
    g.strokeRect(4, 32, 40, 32);

    // Angled terminal head
    poly(g, [{ x: 2, y: 32 }, { x: 46, y: 32 }, { x: 42, y: 8 }, { x: 6, y: 8 }], 0x0b1120, 1);
    outline(g, [{ x: 2, y: 32 }, { x: 46, y: 32 }, { x: 42, y: 8 }, { x: 6, y: 8 }], 0x00cfff, 0.85, 2);

    // Glowing holographic interface screen
    g.fillStyle(0x00cfff, 0.85);
    g.fillRect(10, 12, 28, 16);
    g.fillStyle(0xffffff, 0.9);
    g.fillRect(14, 15, 20, 2);
    g.fillRect(14, 19, 14, 2);
    g.fillRect(14, 23, 17, 2);

    // Pulsing energy core light at base
    g.fillStyle(0x00cfff, 1);
    g.fillCircle(24, 48, 5);
  });

  // Stage 2: Vertical Launch Pad / Kinetic Jump Pad
  forge(scene, 'launch_pad', 64, 24, (g) => {
    // Heavy base housing
    g.fillStyle(0x16293a, 1);
    g.fillRect(2, 8, 60, 16);
    g.lineStyle(2, 0x4a6d87, 0.9);
    g.strokeRect(2, 8, 60, 16);

    // Center kinetic energy plate
    g.fillStyle(0x00cfff, 0.9);
    g.fillRect(12, 4, 40, 6);
    g.lineStyle(1.5, 0xe8faff, 1);
    g.strokeRect(12, 4, 40, 6);

    // Upward chevron arrows signaling launch
    for (let i = 0; i < 3; i++) {
      const cx = 20 + i * 12;
      poly(g, [{ x: cx - 4, y: 20 }, { x: cx, y: 14 }, { x: cx + 4, y: 20 }], 0x00cfff, 0.85);
    }
  });

  // Stage 5: Protocol Altar Pedestal
  forge(scene, 'protocol_altar', 96, 72, (g) => {
    // Stepped divine dais
    g.fillStyle(0x16293a, 1);
    g.fillRect(6, 48, 84, 24);
    g.lineStyle(2, 0x00cfff, 0.8);
    g.strokeRect(6, 48, 84, 24);

    // Central pillar
    g.fillStyle(0x2b3a4d, 1);
    g.fillRect(20, 16, 56, 32);
    g.lineStyle(1.5, 0xe8faff, 0.7);
    g.strokeRect(20, 16, 56, 32);

    // Upper offering lip with harmonic sigil
    g.fillStyle(0x00cfff, 0.9);
    g.fillRect(14, 10, 68, 6);
    g.fillCircle(48, 32, 8);
    g.fillStyle(0xffffff, 1);
    g.fillCircle(48, 32, 3);
  });

  // Stage 5: The Protocol Fragment Crystal
  forge(scene, 'protocol_fragment', 48, 48, (g) => {
    // Radiant crystalline shard
    poly(
      g,
      [
        { x: 24, y: 4 },
        { x: 42, y: 18 },
        { x: 36, y: 44 },
        { x: 12, y: 44 },
        { x: 6, y: 18 },
      ],
      0x00cfff,
      0.95
    );
    // Inner facets
    poly(
      g,
      [
        { x: 24, y: 8 },
        { x: 36, y: 20 },
        { x: 24, y: 38 },
        { x: 12, y: 20 },
      ],
      0xffffff,
      0.85
    );
    outline(
      g,
      [
        { x: 24, y: 4 },
        { x: 42, y: 18 },
        { x: 36, y: 44 },
        { x: 12, y: 44 },
        { x: 6, y: 18 },
      ],
      0xe8faff,
      1,
      2
    );
  });
}
